js='''const data=JSON.parse(document.getElementById('candidateData').textContent);const q=document.getElementById('query'),tag=document.getElementById('tag'),tier=document.getElementById('tier'),body=document.querySelector('#candTable tbody');function esc(x){return String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}function render(){const term=q.value.trim().toLocaleLowerCase();const filtered=data.filter(x=>(!term||JSON.stringify(x).toLocaleLowerCase().includes(term))&&(!tag.value||(x.tag_names??[]).includes(tag.value))&&(!tier.value||x.recommendation===tier.value));document.getElementById('resultCount').textContent=filtered.length+' / '+data.length+' アイテム';body.innerHTML=filtered.map(x=>'<tr><td>'+esc(x.company)+'<br>'+esc((x.booths??[]).join('／'))+'</td><td>'+esc(x.recommendation)+'<br>'+esc((x.tag_names??[]).join('／'))+'</td><td><a href="'+esc(x.main_url||x.company_url)+'">'+esc(x.item)+'</a><br>'+esc(x.exhibit)+'<br>'+esc(x.exhibit_note)+'</td><td>'+esc(x.method)+'<details><summary>限界・確認事項</summary><p>'+esc(x.limits)+'</p><p>'+esc(x.question_text).replace(/\\n/g,'<br>')+'</p><p class="meta">'+esc(x.current_review)+'</p></details></td></tr>').join('');}q.addEventListener('input',render);tag.addEventListener('change',render);tier.addEventListener('change',render);document.getElementById('reset').addEventListener('click',()=>{q.value='';tag.value='';tier.value='';render();});render();'''
